	      currentDisplay.model ||
	      currentDisplay.main ||
	      currentDisplay.builtin ||
	      currentDisplay.connection ||
	      currentDisplay.sizeX !== null ||
	      currentDisplay.pixelDepth !== null ||
	      currentDisplay.resolutionX !== null
